import { Match as M, Schema as S } from "effect";
import { Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as RadioGroup from "../../ui/base-ui-radio";

type Apple = "Fuji" | "Gala" | "Granny Smith";

const AppleRadioGroup = RadioGroup.create<Apple>();
const apples: readonly Apple[] = ["Fuji", "Gala", "Granny Smith"];

// MODEL

export const Model = S.Struct({
  radioGroup: RadioGroup.Model,
});

export type Model = typeof Model.Type;

// MESSAGE

export const GotRadioGroupMessage = m("GotRadioGroupMessage", {
  message: RadioGroup.Message,
});

export const Message = S.Union([GotRadioGroupMessage]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => {
  const [radioGroup, radioGroupCommands] = RadioGroup.init({
    id: "radio-group-basic",
    selectedValue: "Fuji",
  });

  return [
    { radioGroup },
    Command.mapMessages(radioGroupCommands, (message) =>
      GotRadioGroupMessage({ message })
    ),
  ];
};

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotRadioGroupMessage: ({ message }) => {
        const [radioGroup, radioGroupCommands] = AppleRadioGroup.update(
          model.radioGroup,
          message
        );

        return [
          evo(model, { radioGroup: () => radioGroup }),
          Command.mapMessages(radioGroupCommands, (message) =>
            GotRadioGroupMessage({ message })
          ),
        ];
      },
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.submodel({
    slotId: model.radioGroup.id,
    model: model.radioGroup,
    view: AppleRadioGroup.view,
    viewInputs: {
      options: apples,
      ariaLabel: "Best apple",
      name: "apple",
      toView: ({ group, hiddenInput, options }) =>
        h.div(
          [...group, h.Class(RadioGroup.baseUiRadioVerticalClasses)],
          [
            h.input(hiddenInput),
            h.div(
              [h.Class(RadioGroup.baseUiRadioLabelClasses)],
              ["Best apple"]
            ),
            ...options.map((option) =>
              h.label(
                [
                  ...option.label,
                  h.Class("flex cursor-pointer items-center gap-2"),
                ],
                [
                  h.span(
                    [
                      ...option.option,
                      h.Class(RadioGroup.baseUiRadioVerticalOptionClasses),
                    ],
                    [
                      option.isSelected
                        ? RadioGroup.baseUiRadioCheckIcon()
                        : RadioGroup.baseUiRadioCheckPlaceholder(),
                    ]
                  ),
                  h.span(
                    [h.Class(RadioGroup.baseUiRadioLabelClasses)],
                    [option.value]
                  ),
                ]
              )
            ),
          ]
        ),
    },
    toParentMessage: (message) => GotRadioGroupMessage({ message }),
  });
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Radio from "../../ui/base-ui-radio";
import * as BaseUiRadioBasicExample from "./main";

describe("Base UI radio Basic example", () => {
  test("updates selected apple", () => {
    Scene.scene(
      {
        update: BaseUiRadioBasicExample.update,
        view: BaseUiRadioBasicExample.view,
      },
      Scene.with(BaseUiRadioBasicExample.init()[0]),
      Scene.expect(Scene.text("Best apple")).toExist(),
      Scene.expect(Scene.role("radio", { name: "Fuji" })).toBeChecked(),
      Scene.expect(Scene.role("radio", { name: "Gala" })).not.toBeChecked(),
      Scene.expect(
        Scene.role("radio", { name: "Granny Smith" })
      ).not.toBeChecked(),
      Scene.expect(Scene.text("Sweet and crisp.")).not.toExist(),
      Scene.click(Scene.role("radio", { name: "Gala" })),
      Scene.Command.expectHas(
        Radio.FocusOption({ id: "radio-group-basic", index: 1 })
      ),
      Scene.Command.resolve(
        Radio.FocusOption({ id: "radio-group-basic", index: 1 }),
        Radio.CompletedFocusOption(),
        (message) => BaseUiRadioBasicExample.GotRadioGroupMessage({ message })
      ),
      Scene.expect(Scene.role("radio", { name: "Gala" })).toBeChecked()
    );
  });
});
